// AI dictionary, part 1 (A to E). Each term: [English, Hinglish] for the one line meaning, the
// detailed explanation and an everyday example, plus the lessons that teach it and related terms.
// glossary.js sorts all parts alphabetically and renders them (Learn view and glossary page).
var GLOSSARY_TERMS = (typeof GLOSSARY_TERMS !== "undefined" ? GLOSSARY_TERMS : []).concat((function () {
  const t = (term, cat, aka, short, detail, example, lessons = [], related = []) => ({ term, cat, aka, short, detail, example, lessons, related });
  return [
    t("A/B test", "product", "Split test, online experiment",
      ["Randomly showing two versions to different users to see which one really works better.", "Do versions ko randomly alag users ko dikhana, yeh dekhne ke liye ki kaunsa sach mein behtar hai."],
      ["Users are split at random into a control group (the current version) and a treatment group (the new version). Because the split is random, the only systematic difference between the groups is the change, so a difference in results can be called a real effect rather than a coincidence. You decide the main metric and the guardrail metrics before starting, run for the planned time, and check whether the difference is statistically significant.", "Users ko randomly control group (purana version) aur treatment group (naya version) mein baanta jaata hai. Split random hai, isliye groups ke beech systematic fark sirf badlaav ka hota hai, aur results ka fark sach mein asar maana ja sakta hai, sanyog nahi. Main metric aur guardrail metrics shuru se pehle tay karo, planned time tak chalao, aur check karo ki fark statistically significant hai ya nahi."],
      ["Half of the users see AI reply suggestions, half don't; you compare how fast tickets get solved.", "Aadhe users ko AI reply suggestions dikhte hain, aadhon ko nahi; phir compare karte ho tickets kitni jaldi solve hue."],
      ["ab-testing", "stats-correlation"], ["Guardrail metric", "Metric"]),
    t("Ablation study", "dl", "",
      ["Removing one part of a system at a time to see how much each part really helps.", "System ka ek ek hissa hata kar dekhna ki har hissa asal mein kitni madad karta hai."],
      ["If a new model has three changes and scores better, an ablation study turns off each change in turn and measures the score again. It shows which changes matter, which add only complexity, and makes research results believable. Good ablations change one thing at a time and repeat runs with different random seeds so differences aren't noise.", "Agar naye model mein teen badlaav hain aur score behtar hai, to ablation study baari baari har badlaav band karke score dobara naapti hai. Isse pata chalta hai kaunse badlaav zaroori hain, kaunse sirf complexity badhaate hain, aur research ke results pe bharosa hota hai. Acchi ablations ek baar mein ek cheez badalti hain aur alag random seeds se runs dohraati hain taaki fark sirf noise na ho."],
      ["Removing the reranker from a RAG system drops answer accuracy from 86% to 74%, so the reranker clearly helps.", "RAG system se reranker hataane pe answer accuracy 86% se 74% ho jaati hai, matlab reranker saaf madad kar raha hai."],
      ["research-papers"], ["Benchmark", "Evals"]),
    t("Accuracy", "ml", "",
      ["The share of all predictions that were correct.", "Saari predictions mein se kitni sahi thi, uska hissa."],
      ["Accuracy = correct predictions ÷ all predictions. It's easy to understand but misleading when one class is rare: if 1% of payments are fraud, a model that always says 'not fraud' is 99% accurate and completely useless. For imbalanced problems, look at precision, recall and the confusion matrix, and always compare against a simple baseline.", "Accuracy = sahi predictions ÷ saari predictions. Samajhna aasaan hai par tab misleading hai jab ek class rare ho: agar 1% payments fraud hain, to hamesha 'fraud nahi' bolne wala model 99% accurate hai aur bilkul bekaar. Imbalanced problems mein precision, recall aur confusion matrix dekho, aur hamesha simple baseline se compare karo."],
      ["A spam filter that's right on 950 of 1,000 emails has 95% accuracy.", "Jo spam filter 1,000 mein se 950 emails pe sahi hai, uski accuracy 95% hai."],
      ["ml-metrics"], ["Precision", "Recall", "Confusion matrix", "Baseline"]),
    t("Activation function", "dl", "ReLU, sigmoid, GELU",
      ["A small maths function inside each neuron that lets neural networks learn curves, not just straight lines.", "Har neuron ke andar ek chhota maths function jisse neural networks sirf seedhi lines nahi, curves bhi seekh paate hain."],
      ["Each neuron computes a weighted sum of its inputs and passes it through an activation function. Without it, stacking layers would still only produce a straight line relationship. ReLU (keep positives, zero negatives) is the common default in hidden layers; GELU is used in transformers; sigmoid and softmax turn outputs into probabilities.", "Har neuron apne inputs ka weighted sum nikaalta hai aur use activation function se guzaarta hai. Iske bina layers jodne pe bhi sirf seedhi line wala rishta banta. Hidden layers mein ReLU (positive rakho, negative ko zero) common default hai; transformers mein GELU; sigmoid aur softmax outputs ko probabilities mein badalte hain."],
      ["ReLU turns -3 into 0 and keeps 5 as 5.", "ReLU -3 ko 0 bana deta hai aur 5 ko 5 hi rehne deta hai."],
      ["dl-neural-networks"], ["Neural network", "Softmax"]),
    t("Agent (AI agent)", "agents", "Autonomous agent",
      ["An LLM that works in a loop: plans a step, uses a tool, looks at the result, and decides the next step until the goal is done.", "Ek LLM jo loop mein kaam karta hai: step plan karta hai, tool use karta hai, result dekhta hai, aur goal poora hone tak agla step tay karta hai."],
      ["An agent gets a goal and a set of tools (search, database lookup, sending an email). In each turn the model decides which tool to call; your code runs the tool and gives the result back. This suits open ended tasks where the steps aren't known in advance. Because each step costs time and money and can go wrong, agents need limits (max steps, budgets), human approval for risky actions, tracing and evaluation. If the steps are fixed, a simple workflow is better.", "Agent ko ek goal aur kuch tools milte hain (search, database lookup, email bhejna). Har turn mein model tay karta hai kaunsa tool call karna hai; aapka code tool chalata hai aur result wapas deta hai. Yeh un open ended kaamon ke liye accha hai jinke steps pehle se pata nahi. Har step mein time aur paisa lagta hai aur galti ho sakti hai, isliye agents ko limits (max steps, budget), risky actions pe human approval, tracing aur evaluation chahiye. Steps fixed hon to simple workflow behtar hai."],
      ["A support agent looks up the order, checks the refund policy and drafts a reply for a human to approve.", "Support agent order dhoondhta hai, refund policy check karta hai aur insaan ke approval ke liye reply draft karta hai."],
      ["llm-agents", "llm-tool-use"], ["Tool calling", "MCP", "Guardrails", "Workflow"]),
    t("AI (artificial intelligence)", "basics", "",
      ["Computer systems that do things we'd normally call smart: understand language, recognise images, make decisions.", "Aise computer systems jo woh kaam karte hain jinhe hum samajhdaari kehte: bhasha samajhna, images pehchaanna, faisle lena."],
      ["AI is the big umbrella. Older AI used hand written rules; most modern AI is machine learning, where the system learns patterns from examples. Deep learning and generative AI (like ChatGPT or Claude) are parts of machine learning. In jobs, 'AI' usually means building products and systems around these models.", "AI ek bada umbrella hai. Purana AI haath se likhe rules use karta tha; aaj ka zyaadatar AI machine learning hai, jahan system examples se patterns seekhta hai. Deep learning aur generative AI (jaise ChatGPT ya Claude) machine learning ke hisse hain. Jobs mein 'AI' ka matlab aksar in models ke around products aur systems banana hota hai."],
      ["Face unlock, map traffic predictions and voice assistants are all AI.", "Face unlock, map ki traffic predictions aur voice assistants, sab AI hain."],
      ["what-is-ai"], ["Machine learning", "Deep learning", "Generative AI"]),
    t("AI engineer", "product", "LLM engineer, applied AI engineer",
      ["A software engineer who builds products and systems using AI models, especially LLMs.", "Software engineer jo AI models, khaaskar LLMs, use karke products aur systems banata hai."],
      ["AI engineers usually don't train big models from scratch. They connect models to real data and apps: prompts, RAG, tool calling, agents, evaluation, guardrails, latency and cost. Strong software engineering matters more than heavy maths. Related roles include ML engineer (trains and serves models), MLOps engineer (runs them reliably) and AI product engineer (ships user facing AI features).", "AI engineers aam taur pe bade models shuru se train nahi karte. Woh models ko asli data aur apps se jodte hain: prompts, RAG, tool calling, agents, evaluation, guardrails, latency aur cost. Bhaari maths se zyaada mazboot software engineering zaroori hai. Jude roles: ML engineer (models train aur serve karta hai), MLOps engineer (unhe reliably chalata hai) aur AI product engineer (users ke liye AI features ship karta hai)."],
      ["Building a company chatbot that answers from HR policies with citations is typical AI engineer work.", "HR policies se citations ke saath jawaab dene wala company chatbot banana typical AI engineer ka kaam hai."],
      ["job-search", "llm-api"], ["RAG", "Agent (AI agent)", "MLOps"]),
    t("Alignment", "eval", "",
      ["Making AI models behave the way people intend: helpful, honest and safe.", "AI models ko waisa behave karwana jaisa log chahte hain: madadgaar, imaandaar aur safe."],
      ["A model trained only to predict text can produce harmful, false or unhelpful output. Alignment techniques, such as instruction tuning, RLHF, DPO and constitutional methods, teach the model to follow instructions, refuse harmful requests and admit uncertainty. In products, alignment is supported by system prompts, guardrails and evaluation.", "Sirf text predict karne ke liye train hua model nuksaandeh, galat ya bekaar output de sakta hai. Alignment techniques, jaise instruction tuning, RLHF, DPO aur constitutional methods, model ko instructions maanna, nuksaandeh requests mana karna aur anishchitata maanna sikhaati hain. Products mein alignment ko system prompts, guardrails aur evaluation sahaara dete hain."],
      ["A chatbot politely refusing to explain how to make a weapon is alignment at work.", "Chatbot ka hathiyar banane ka tarika batane se vinamrata se mana karna alignment ka kaam hai."],
      ["llm-safety"], ["RLHF", "Guardrails", "Hallucination"]),
    t("Annotation (labelling)", "data", "Data labelling",
      ["Adding the correct answers (labels) to data so a model can learn from it.", "Data mein sahi jawaab (labels) jodna taaki model usse seekh sake."],
      ["Supervised learning needs labelled examples: emails marked spam or not, images with boxes around cars, tickets tagged by category. Labels are made by people, by rules, or by an LLM checked by people. Clear labelling guidelines and checking agreement between labellers matter, because the model copies label mistakes.", "Supervised learning ko labelled examples chahiye: spam ya not spam mark kiye emails, gaadiyon ke around box wali images, category se tag kiye tickets. Labels log, rules, ya insaanon se check kiya LLM banata hai. Saaf labelling guidelines aur labellers ke beech agreement check karna zaroori hai, kyunki model label ki galtiyaan bhi copy karta hai."],
      ["Tagging 2,000 support tickets as billing, delivery or technical to train a classifier.", "Classifier train karne ke liye 2,000 support tickets ko billing, delivery ya technical tag karna."],
      ["ml-how-machines-learn"], ["Label", "Supervised learning", "Dataset"]),
    t("API", "basics", "Application Programming Interface",
      ["A defined way for one program to ask another program for data or an action.", "Ek program ka doosre program se data ya kaam maangne ka tay kiya hua tarika."],
      ["An API defines what you can request and what you get back, usually as JSON over HTTP. LLM providers offer APIs: you send a model name and messages, and receive the generated text and token counts. In AI products you both call APIs (LLMs, databases) and expose your own (for example a /predict endpoint for your model).", "API tay karta hai aap kya maang sakte ho aur badle mein kya milega, aam taur pe HTTP pe JSON. LLM providers APIs dete hain: aap model ka naam aur messages bhejte ho, aur generated text aur token counts milte hain. AI products mein aap APIs call bhi karte ho (LLMs, databases) aur apni bhi dete ho (jaise model ke liye /predict endpoint)."],
      ["A weather app calls a weather API to get today's forecast.", "Weather app aaj ka forecast lene ke liye weather API call karta hai."],
      ["llm-api", "api-serving"], ["Inference", "Latency"]),
    t("Attention (self attention)", "dl", "",
      ["The mechanism in transformers that lets each word look at every other word to understand its meaning in context.", "Transformers ka woh mechanism jisse har shabd baaki har shabd ko dekhkar context mein apna matlab samajhta hai."],
      ["Each token creates a query, a key and a value vector. Comparing a token's query with every key gives attention weights (how relevant each other token is), and the token's new representation is a weighted mix of the values. So 'bank' near 'river' ends up different from 'bank' near 'loan'. Attention cost grows with the square of the text length, which is why long contexts are expensive.", "Har token ek query, ek key aur ek value vector banata hai. Token ki query ko har key se compare karne pe attention weights milte hain (baaki token kitne relevant hain), aur token ki nayi representation values ka weighted mix hoti hai. Isliye 'river' ke paas wala 'bank' 'loan' ke paas wale 'bank' se alag ban jaata hai. Attention ka kharch text ki lambai ke square ke saath badhta hai, isliye lambe contexts mehenge hain."],
      ["In 'The animal didn't cross the road because it was tired', attention links 'it' to 'animal'.", "'The animal didn't cross the road because it was tired' mein attention 'it' ko 'animal' se jodta hai."],
      ["dl-transformers"], ["Transformer", "KV cache", "Token"]),
    t("AUC (ROC AUC, PR AUC)", "ml", "Area under the curve",
      ["A single number summarising how well a model separates positives from negatives across all thresholds.", "Ek number jo batata hai model saare thresholds pe positives ko negatives se kitna acche se alag karta hai."],
      ["ROC AUC is the chance that the model scores a random positive higher than a random negative: 0.5 is guessing, 1.0 is perfect. PR AUC summarises precision and recall together and is more informative when positives are rare, like fraud. AUC doesn't pick a threshold for you; you still choose one for the business trade off.", "ROC AUC woh chance hai ki model ek random positive ko random negative se zyaada score de: 0.5 matlab andaaza, 1.0 matlab perfect. PR AUC precision aur recall ko saath mein summarise karta hai aur tab zyaada kaam ka hai jab positives rare hon, jaise fraud. AUC aapke liye threshold nahi chunta; business trade off ke liye threshold aapko khud chunna hai."],
      ["A fraud model with ROC AUC 0.92 ranks fraud above normal payments 92% of the time.", "ROC AUC 0.92 wala fraud model 92% baar fraud ko normal payments se upar rank karta hai."],
      ["ml-metrics"], ["Precision", "Recall", "Threshold"]),
    t("Autoscaling", "mlops", "HPA",
      ["Automatically adding or removing servers as traffic goes up or down.", "Traffic badhne ya ghatne pe apne aap servers jodna ya hataana."],
      ["When load rises, more copies (replicas) of the service start; when it falls, they're removed to save cost. Kubernetes' Horizontal Pod Autoscaler scales on CPU, memory or custom metrics; for LLM servers, queue length or tokens per second are better signals. Models take time to load, so plan headroom and readiness checks.", "Load badhne pe service ki aur copies (replicas) start hoti hain; ghatne pe cost bachaane ke liye hata di jaati hain. Kubernetes ka Horizontal Pod Autoscaler CPU, memory ya custom metrics pe scale karta hai; LLM servers ke liye queue length ya tokens per second behtar signals hain. Models load hone mein time lete hain, isliye headroom aur readiness checks plan karo."],
      ["During a festival sale the recommendation service grows from 4 to 20 replicas, then shrinks at night.", "Festival sale mein recommendation service 4 se 20 replicas ho jaati hai, phir raat ko ghat jaati hai."],
      ["kubernetes", "gpu-serving"], ["Kubernetes", "Latency", "Inference"]),
    t("Backpropagation", "dl", "Backprop",
      ["The method neural networks use to work out how much each weight contributed to the error, so it can be adjusted.", "Woh tarika jisse neural network pata lagata hai har weight ne error mein kitna yogdaan diya, taaki use badla ja sake."],
      ["After a forward pass produces a prediction and a loss, backpropagation applies the chain rule from the output back to the first layer, computing the gradient of the loss for every weight. An optimiser like SGD or Adam then nudges the weights. Frameworks such as PyTorch do this automatically (autograd).", "Forward pass se prediction aur loss milne ke baad, backpropagation output se pehli layer tak chain rule lagata hai aur har weight ke liye loss ka gradient nikaalta hai. Phir SGD ya Adam jaisa optimiser weights ko thoda khiskaata hai. PyTorch jaise frameworks yeh apne aap karte hain (autograd)."],
      ["Like a teacher tracing which step in a long sum caused the wrong answer.", "Jaise teacher dhoondhe ki lambe sawaal ka kaunsa step galat jawaab ki wajah bana."],
      ["math-gradients", "dl-neural-networks"], ["Gradient", "Gradient descent", "Loss function"]),
    t("Baseline", "ml", "",
      ["A simple reference result that any new model must beat to be worth using.", "Ek simple reference result jise naye model ko use ke layak hone ke liye harana hi chahiye."],
      ["Baselines include 'always predict the most common class', 'predict yesterday's value', a simple rule, or the current human process. Without a baseline, a score like 85% means nothing. Baselines also catch bugs: if a fancy model barely beats a trivial one, something may be wrong.", "Baselines mein 'hamesha sabse common class predict karo', 'kal ki value predict karo', ek simple rule, ya aaj ka insaani process hota hai. Baseline ke bina 85% jaisa score kuch nahi batata. Baselines bugs bhi pakadte hain: agar fancy model ek simple wale ko mushkil se harata hai, to kuch gadbad ho sakti hai."],
      ["If 90% of loans are repaid, a model must beat 90% accuracy to be useful.", "Agar 90% loans chukaaye jaate hain, to model ko kaam ka hone ke liye 90% accuracy harani hogi."],
      ["ml-metrics", "ml-regression-classification"], ["Accuracy", "Benchmark"]),
    t("Batch inference", "mlops", "Offline scoring",
      ["Running a model on many records at once on a schedule, instead of one request at a time.", "Ek ek request ke bajaye schedule pe bahut saare records pe ek saath model chalana."],
      ["Batch inference scores large sets, for example every customer's churn risk each night, and stores the results for apps to read. It's simpler and cheaper than real time serving and fine when predictions don't need to be instant. Real time inference is needed when a decision must happen within a request, like blocking a fraudulent payment.", "Batch inference bade sets score karta hai, jaise har raat har customer ka churn risk, aur results store karta hai jo apps padhti hain. Yeh real time serving se simple aur sasta hai aur tab theek hai jab predictions turant na chahiye hon. Real time inference tab chahiye jab faisla request ke andar hi lena ho, jaise fraud payment rokna."],
      ["A bank scores all credit card customers every night for next day offers.", "Bank har raat saare credit card customers ko agle din ke offers ke liye score karta hai."],
      ["ml-training-vs-inference"], ["Inference", "Latency", "Data pipeline"]),
    t("Batch size", "dl", "",
      ["How many examples a model processes together in one training step.", "Ek training step mein model ek saath kitne examples process karta hai."],
      ["Training updates weights after each mini batch rather than after every example or the whole dataset. Larger batches use the GPU efficiently but need more memory; smaller batches are noisier but can generalise well. In LLM serving, batching many user requests together raises throughput and lowers cost per request.", "Training har example ya poore dataset ke baad nahi, har mini batch ke baad weights update karti hai. Bade batches GPU ka accha use karte hain par zyaada memory chahiye; chhote batches mein zyaada noise hota hai par generalise acche se kar sakte hain. LLM serving mein bahut saari user requests saath batch karne se throughput badhta aur per request cost ghatta hai."],
      ["Training with batch size 32 means the model looks at 32 images before each weight update.", "Batch size 32 se training matlab model har weight update se pehle 32 images dekhta hai."],
      ["math-gradients", "gpu-serving"], ["Epoch", "Gradient descent", "GPU"]),
    t("Benchmark", "eval", "",
      ["A standard test set used to compare models fairly.", "Models ko nishpaksh tarike se compare karne ke liye ek standard test set."],
      ["Public benchmarks (for maths, coding, reasoning, retrieval) let teams compare models on the same questions. They're useful but limited: models can be tuned to them, and a high public score doesn't guarantee good results on your task. For products, build your own eval set from real cases.", "Public benchmarks (maths, coding, reasoning, retrieval ke liye) teams ko same sawaalon pe models compare karne dete hain. Kaam ke hain par seemit: models unke liye tune ho sakte hain, aur ooncha public score aapke task pe acche results ki guarantee nahi. Products ke liye asli cases se apna eval set banao."],
      ["Comparing two embedding models on the same retrieval benchmark before choosing one.", "Ek chunne se pehle do embedding models ko same retrieval benchmark pe compare karna."],
      ["llm-evals", "research-papers"], ["Evals", "Test set"]),
    t("Bias (in data and models)", "eval", "Fairness",
      ["When a model's results are systematically unfair or skewed, often because of skewed training data.", "Jab model ke results lagaataar ek taraf jhuke ya anyaayi hon, aksar jhuke hue training data ki wajah se."],
      ["Models learn patterns in their data, including historical unfairness and gaps. A hiring model trained on past hires can repeat past discrimination; a face model trained mostly on one group performs worse on others. Check performance across groups, fix data coverage, avoid sensitive features where inappropriate, and keep humans accountable for high stakes decisions.", "Models apne data ke patterns seekhte hain, purana anyaay aur kamiyaan samet. Purane hires pe train hua hiring model purana bhedbhaav dohra sakta hai; zyaadatar ek group pe train hua face model doosron pe kharab karta hai. Alag groups pe performance check karo, data coverage theek karo, jahan sahi na ho wahan sensitive features se bacho, aur high stakes faislon ke liye insaanon ko zimmedaar rakho."],
      ["A loan model approving far fewer applicants from one region with the same income is a bias warning sign.", "Same income ke bawajood ek region ke kaafi kam applicants approve karne wala loan model bias ka warning sign hai."],
      ["stats-correlation", "llm-safety"], ["Sampling bias", "Explainability"]),
    t("Bias variance trade off", "ml", "",
      ["The balance between a model that's too simple (misses patterns) and too complex (memorises noise).", "Bahut simple (patterns chhoot jaate hain) aur bahut complex (noise ratt leta hai) model ke beech ka santulan."],
      ["High bias means underfitting: the model is too simple, so it's wrong on training and new data alike. High variance means overfitting: it fits training data closely but fails on new data. Increasing complexity lowers bias but raises variance. You find the sweet spot using validation data, regularisation and more data.", "High bias matlab underfitting: model bahut simple hai, training aur naye dono data pe galat. High variance matlab overfitting: training data pe kareeb fit, par naye data pe fail. Complexity badhaane se bias ghatta aur variance badhta hai. Sweet spot validation data, regularisation aur zyaada data se milta hai."],
      ["A straight line through curved sales data has high bias; a 50 level decision tree has high variance.", "Curved sales data pe seedhi line high bias hai; 50 level ka decision tree high variance."],
      ["ml-train-test"], ["Overfitting", "Underfitting", "Regularisation"]),
    t("BM25 (keyword search)", "llm", "Lexical search",
      ["A classic search method that ranks documents by matching words, used with vector search in hybrid search.", "Shabdon ke match se documents rank karne ka classic search tarika, hybrid search mein vector search ke saath use hota hai."],
      ["BM25 scores a document higher when it contains the query's words, especially rare words, and adjusts for document length. It's excellent for exact terms like product codes, names and error numbers, where embeddings are weak. Combining BM25 with vector search (hybrid search) usually improves RAG retrieval.", "BM25 document ko tab zyaada score deta hai jab usme query ke shabd, khaaskar rare shabd, hon, aur document ki lambai ke hisaab se adjust karta hai. Product codes, naam aur error numbers jaise exact terms ke liye badhiya hai, jahan embeddings kamzor hain. BM25 ko vector search ke saath milana (hybrid search) aksar RAG retrieval sudhaarta hai."],
      ["Searching 'ERR_4012' finds the exact troubleshooting page with BM25.", "'ERR_4012' search karne pe BM25 exact troubleshooting page dhoondh leta hai."],
      ["rag", "embeddings"], ["Hybrid search", "Semantic search", "RAG"]),
    t("Chain of thought", "llm", "CoT, reasoning",
      ["Asking a model to reason step by step before giving the final answer.", "Model se final jawaab se pehle step by step sochne ko kehna."],
      ["Writing out intermediate steps helps models on maths, logic and multi step problems. Many modern 'reasoning' models do this internally before answering. In products, you usually show users only the final answer, and you still check results, because reasoning that sounds right can be wrong.", "Beech ke steps likhne se models ko maths, logic aur multi step problems mein madad milti hai. Kai naye 'reasoning' models jawaab se pehle yeh andar hi karte hain. Products mein users ko aam taur pe sirf final jawaab dikhaate ho, aur results phir bhi check karte ho, kyunki sahi lagne wali reasoning bhi galat ho sakti hai."],
      ["'First find the total cost, then the discount, then the final price' improves a model's maths answer.", "'Pehle total cost nikalo, phir discount, phir final price' se model ka maths jawaab sudharta hai."],
      ["llm-prompting"], ["Prompt engineering", "Few shot prompting"]),
    t("Chatbot", "llm", "Conversational AI",
      ["A program you talk with in natural language; modern chatbots are usually powered by LLMs.", "Program jisse aap normal bhasha mein baat karte ho; aaj ke chatbots aksar LLMs se chalte hain."],
      ["Old chatbots followed scripted rules and buttons. LLM chatbots understand free text and generate answers, often grounded in company documents with RAG and connected to tools for actions. Good chatbots show sources, say when they don't know, and hand over to a human when needed.", "Purane chatbots scripted rules aur buttons follow karte the. LLM chatbots khula text samajhte aur jawaab banate hain, aksar RAG se company documents pe based aur actions ke liye tools se jude. Acche chatbots sources dikhate hain, na pata ho to batate hain, aur zaroorat ho to insaan ko saunp dete hain."],
      ["A bank's assistant that answers card questions from policy documents.", "Bank ka assistant jo policy documents se card ke sawaalon ka jawaab deta hai."],
      ["llm-what", "rag", "ai-ux"], ["LLM", "RAG", "Agent (AI agent)"]),
    t("Chunking", "llm", "",
      ["Splitting documents into smaller pieces before embedding them for search and RAG.", "Search aur RAG ke liye embed karne se pehle documents ko chhote tukdon mein todna."],
      ["Models and vector search work best on focused passages. Chunks should hold a complete idea: split along headings, paragraphs and tables rather than every N characters, often a few hundred tokens with a small overlap, and store title, section, date and permissions as metadata. Test chunk sizes against real questions; bad chunking is a top cause of wrong RAG answers.", "Models aur vector search focused passages pe sabse accha kaam karte hain. Chunk mein poora idea hona chahiye: har N characters ke bajaye headings, paragraphs aur tables ke hisaab se todo, aksar kuch sau tokens thode overlap ke saath, aur title, section, date aur permissions metadata mein rakho. Asli sawaalon pe chunk sizes test karo; galat chunking galat RAG jawaabon ki badi wajah hai."],
      ["A 40 page policy PDF becomes 120 chunks, one per section or paragraph group.", "40 page ki policy PDF 120 chunks ban jaati hai, har section ya paragraph group ka ek."],
      ["rag", "embeddings"], ["RAG", "Embedding", "Vector database"]),
    t("CI/CD", "mlops", "Continuous integration and delivery",
      ["Automatically testing and releasing code (and models) every time something changes.", "Har badlaav pe code (aur models) ko apne aap test aur release karna."],
      ["Continuous integration runs tests on every change; continuous delivery deploys passing changes safely. For ML, add data validation, a small training run, evaluation against a fixed set before promotion, and gradual rollouts with rollback. Tools include GitHub Actions, Jenkins and GitLab CI.", "Continuous integration har badlaav pe tests chalata hai; continuous delivery paas hue badlaav safely deploy karta hai. ML mein data validation, chhota training run, promotion se pehle fixed set pe evaluation, aur rollback ke saath dheere rollouts jodo. Tools: GitHub Actions, Jenkins aur GitLab CI."],
      ["A pull request automatically runs unit tests and an eval suite before it can be merged.", "Pull request merge hone se pehle apne aap unit tests aur eval suite chalata hai."],
      ["mlops-tracking", "git-github"], ["MLOps", "Model registry", "Evals"]),
    t("Classification", "ml", "Classifier",
      ["Predicting a category, like spam or not spam, or which department a ticket belongs to.", "Ek category predict karna, jaise spam ya not spam, ya ticket kis department ka hai."],
      ["Classification models output a class or class probabilities. Binary classification has two classes; multi class has several. Common models are logistic regression, gradient boosted trees and neural networks; LLMs can also classify text with a good prompt. Evaluate with precision, recall, F1 and a confusion matrix.", "Classification models ek class ya class probabilities dete hain. Binary classification mein do classes; multi class mein kai. Common models: logistic regression, gradient boosted trees aur neural networks; accha prompt ho to LLMs bhi text classify kar sakte hain. Precision, recall, F1 aur confusion matrix se evaluate karo."],
      ["Predicting whether a loan applicant will default (yes or no).", "Predict karna ki loan lene wala default karega ya nahi (haan ya nahi)."],
      ["ml-regression-classification", "ml-metrics"], ["Regression", "Precision", "Recall"]),
    t("Clustering", "ml", "K means",
      ["Grouping similar items together without any labels.", "Bina labels ke milti julti cheezon ko groups mein rakhna."],
      ["Clustering is unsupervised learning: the algorithm finds natural groups in data, for example customer segments by behaviour. K means assigns each item to the nearest of K centres and moves the centres until stable. Results need human interpretation: the algorithm doesn't know what the groups mean.", "Clustering unsupervised learning hai: algorithm data mein natural groups dhoondhta hai, jaise behaviour ke hisaab se customer segments. K means har item ko K centres mein se sabse paas wale ko deta hai aur centres ko stable hone tak khiskaata hai. Results ko insaani samajh chahiye: algorithm nahi jaanta groups ka matlab kya hai."],
      ["An online store discovers 'weekend bargain hunters' and 'premium regulars' groups.", "Online store 'weekend bargain hunters' aur 'premium regulars' groups dhoondhta hai."],
      ["ml-how-machines-learn"], ["Unsupervised learning", "Embedding"]),
    t("Computer vision", "dl", "CV",
      ["AI that understands images and video: recognising objects, faces, text and scenes.", "AI jo images aur video samajhta hai: objects, chehre, text aur drishya pehchaanna."],
      ["Tasks include classification (what's in the image), detection (where objects are), segmentation (which pixels belong to what) and OCR (reading text). Modern vision uses convolutional networks and vision transformers, and multimodal LLMs can describe and reason about images.", "Tasks mein classification (image mein kya hai), detection (objects kahan hain), segmentation (kaunse pixels kiske hain) aur OCR (text padhna) hain. Aaj ka vision convolutional networks aur vision transformers use karta hai, aur multimodal LLMs images ka varnan aur un pe reasoning kar sakte hain."],
      ["A phone camera reading a cheque amount, or a factory camera spotting defective parts.", "Phone camera ka cheque ka amount padhna, ya factory camera ka kharab parts pakadna."],
      ["dl-neural-networks"], ["Multimodal", "Deep learning"]),
    t("Concept drift", "mlops", "",
      ["When the relationship between inputs and the right answer changes over time, so a trained model gets worse.", "Jab inputs aur sahi jawaab ka rishta waqt ke saath badal jaata hai, aur trained model kharab hone lagta hai."],
      ["The inputs may look the same, but what they mean has changed, for example fraudsters change tactics or customer preferences shift after a price change. Detect it by tracking real performance when labels arrive, plus proxy signals. Fix it by retraining on recent data, sometimes with new features.", "Inputs same dikh sakte hain, par unka matlab badal gaya hai, jaise fraudsters tarike badalte hain ya price change ke baad customers ki pasand badalti hai. Labels aane pe asli performance track karke aur proxy signals se pakdo. Haal ke data pe retrain karke theek karo, kabhi naye features ke saath."],
      ["A fraud model trained before UPI scams became common misses the new pattern.", "UPI scams common hone se pehle train hua fraud model naya pattern miss kar deta hai."],
      ["mlops-monitoring"], ["Data drift", "Monitoring"]),
    t("Confusion matrix", "ml", "",
      ["A 2×2 (or bigger) table showing correct and wrong predictions for each class.", "2×2 (ya badi) table jo har class ke sahi aur galat predictions dikhati hai."],
      ["For yes or no problems it counts true positives, false positives, false negatives and true negatives. Precision, recall and accuracy are all calculated from it. Looking at the matrix shows which mistakes the model makes, which matters more than a single score.", "Haan ya nahi wali problems mein yeh true positives, false positives, false negatives aur true negatives ginta hai. Precision, recall aur accuracy sab isi se nikalte hain. Matrix dekhne se pata chalta hai model kaunsi galtiyaan karta hai, jo ek score se zyaada zaroori hai."],
      ["Out of 10 frauds, 8 caught (TP), 2 missed (FN); 12 normal payments wrongly flagged (FP).", "10 fraud mein se 8 pakde (TP), 2 chhoote (FN); 12 normal payments galti se flag hue (FP)."],
      ["ml-metrics"], ["Precision", "Recall", "Accuracy"]),
    t("Context window", "llm", "Context length",
      ["The maximum amount of text (in tokens) an LLM can consider at once, including its answer.", "Ek baar mein LLM jitna text (tokens mein) dekh sakta hai uski seema, uske jawaab samet."],
      ["Everything the model sees, system prompt, documents, chat history, tool results and output, must fit in the context window. Bigger windows allow longer documents but cost more and are slower, and models can miss details in the middle of very long inputs. RAG and summarising history keep context focused.", "Model jo kuch dekhta hai, system prompt, documents, chat history, tool results aur output, sab context window mein fit hona chahiye. Badi windows lambe documents allow karti hain par mehngi aur slow hain, aur bahut lambe inputs ke beech ki details model miss kar sakta hai. RAG aur history ka summary context focused rakhte hain."],
      ["A 200,000 token window holds roughly a 500 page book.", "200,000 token ki window lagbhag 500 page ki kitaab sambhaal leti hai."],
      ["llm-what", "llm-api"], ["Token", "RAG", "Lost in the middle"]),
    t("Cosine similarity", "llm", "",
      ["A measure of how similar two vectors point, used to compare the meaning of embeddings.", "Do vectors ki direction kitni milti hai uska naap, embeddings ka matlab compare karne mein use hota hai."],
      ["It's the cosine of the angle between two vectors: 1 means same direction (very similar meaning), 0 unrelated. Vector databases use it (or the closely related dot product) to find the chunks closest in meaning to a question.", "Yeh do vectors ke beech ke angle ka cosine hai: 1 matlab same direction (bahut milta julta matlab), 0 matlab koi rishta nahi. Vector databases ise (ya jude hue dot product ko) use karke sawaal ke matlab ke sabse paas ke chunks dhoondhte hain."],
      ["'reset my password' and 'forgot login' have high cosine similarity.", "'reset my password' aur 'forgot login' ki cosine similarity zyaada hai."],
      ["embeddings", "math-vectors"], ["Embedding", "Vector", "Semantic search"]),
    t("Cross entropy", "dl", "Log loss",
      ["The standard loss function for classification: it punishes confident wrong answers heavily.", "Classification ka standard loss function: confident galat jawaabon ko bhaari saza deta hai."],
      ["Cross entropy compares predicted probabilities with the true class. Predicting 0.9 for the right class gives a small loss; predicting 0.01 for it gives a large loss. LLMs are trained with cross entropy on the next token. Combined with softmax, its gradient is simply prediction minus truth.", "Cross entropy predicted probabilities ko sahi class se compare karta hai. Sahi class ko 0.9 dena chhota loss deta hai; use 0.01 dena bada loss. LLMs agle token pe cross entropy se train hote hain. Softmax ke saath iska gradient bas prediction minus sach hai."],
      ["A cat image predicted as 95% dog gives a big cross entropy loss.", "Billi ki image ko 95% kutta predict karna bada cross entropy loss deta hai."],
      ["math-gradients", "dl-neural-networks"], ["Loss function", "Softmax"]),
    t("Cross validation", "ml", "K fold",
      ["Rotating which part of the data is used for validation to get a more reliable score.", "Validation ke liye data ka hissa baari baari badal kar zyaada bharosemand score paana."],
      ["In k fold cross validation, training data is split into k parts; the model trains on k minus 1 and validates on the remaining one, k times, and the scores are averaged. It's useful for small datasets and tuning. Use time based splits for time series, and group splits when one person has many rows.", "K fold cross validation mein training data k hisson mein baanta jaata hai; model k minus 1 pe train aur bache hue pe validate hota hai, k baar, aur scores ka average liya jaata hai. Chhote datasets aur tuning ke liye kaam ka. Time series ke liye time based splits, aur jab ek insaan ki kai rows hon to group splits."],
      ["5 fold cross validation gives scores 81, 84, 79, 83, 82; average 81.8.", "5 fold cross validation se scores 81, 84, 79, 83, 82; average 81.8."],
      ["ml-train-test"], ["Validation set", "Overfitting"]),
    t("Data drift", "mlops", "Covariate shift",
      ["When the data a live model receives starts to look different from its training data.", "Jab live model ko milne wala data uske training data se alag dikhne lage."],
      ["New customer segments, new devices, a changed form or a broken upstream system can all shift input distributions. Monitor feature and prediction distributions against a baseline (for example with PSI), alert on big shifts, and investigate: sometimes it's a bug, sometimes the world changed and you need to retrain.", "Naye customer segments, naye devices, badla hua form ya toota upstream system, sab input distributions khiska sakte hain. Feature aur prediction distributions ko baseline se monitor karo (jaise PSI se), bade badlaav pe alert, aur jaanch karo: kabhi bug hota hai, kabhi duniya badal gayi hai aur retrain chahiye."],
      ["After launching in a new city, average delivery distances double and the delivery time model drifts.", "Naye shehar mein launch ke baad average delivery distance double hoti hai aur delivery time model drift karta hai."],
      ["mlops-monitoring", "data-quality"], ["Concept drift", "Monitoring"]),
    t("Data leakage", "ml", "Leakage",
      ["When information that won't exist at prediction time sneaks into training, making test scores falsely high.", "Jab prediction ke time na hone wali information training mein ghus jaati hai, aur test scores jhooth mein ooche aate hain."],
      ["Examples: using 'refund issued' to predict fraud, scaling with statistics from the whole dataset before splitting, or the same customer in train and test. The model looks brilliant in testing and fails in production. Ask for every feature: would I know this at the moment of prediction?", "Examples: fraud predict karne ke liye 'refund issued' use karna, split se pehle poore dataset ke statistics se scaling, ya same customer train aur test dono mein. Model testing mein shaandaar dikhta hai aur production mein fail. Har feature ke liye poochho: prediction ke moment pe kya yeh mujhe pata hoga?"],
      ["A churn model scoring 0.99 AUC because it used 'account closed date' as a feature.", "'account closed date' ko feature banane se 0.99 AUC dene wala churn model."],
      ["ml-train-test", "ml-features"], ["Feature", "Test set", "Overfitting"]),
    t("Data pipeline", "data", "ETL pipeline",
      ["Automated steps that move data from sources, clean and transform it, and deliver it for reports or models.", "Apne aap chalne wale steps jo sources se data laate, saaf aur transform karte, aur reports ya models tak pahunchaate hain."],
      ["A pipeline extracts data (databases, APIs, files), loads and transforms it (SQL, dbt, Spark) and publishes clean tables, features or vector indexes. It's orchestrated on a schedule (Airflow) with retries, data quality checks and alerts. Good pipelines are idempotent, so reruns and backfills don't create duplicates.", "Pipeline data nikaalti hai (databases, APIs, files), load aur transform karti hai (SQL, dbt, Spark) aur saaf tables, features ya vector indexes publish karti hai. Schedule pe orchestrate hoti hai (Airflow), retries, data quality checks aur alerts ke saath. Acchi pipelines idempotent hoti hain, taaki reruns aur backfills duplicates na banayein."],
      ["Every night, orders are copied from the app database, cleaned and turned into a sales dashboard table.", "Har raat orders app database se copy, saaf aur sales dashboard table mein badle jaate hain."],
      ["data-pipelines", "data-quality"], ["ETL and ELT", "Idempotency", "Feature store"]),
    t("Dataset", "data", "",
      ["A collection of examples used to train, validate or test a model.", "Model train, validate ya test karne ke liye examples ka collection."],
      ["A dataset might be rows in a table, images with labels, or question and answer pairs. Its quality, coverage and size often matter more than the model choice. Split it into training, validation and test sets, document where it came from, and check for duplicates, bias and leakage.", "Dataset table ki rows, labels wali images, ya sawaal jawaab ke jode ho sakte hain. Iski quality, coverage aur size aksar model ke chunaav se zyaada matter karte hain. Ise training, validation aur test sets mein baanto, kahan se aaya document karo, aur duplicates, bias aur leakage check karo."],
      ["50,000 past loan applications with whether each was repaid.", "50,000 purani loan applications, har ek chukaaya gaya ya nahi uske saath."],
      ["ml-how-machines-learn", "data-quality"], ["Label", "Test set", "Annotation (labelling)"]),
    t("Decision tree", "ml", "",
      ["A model that predicts by asking a series of yes or no questions about the input.", "Model jo input ke baare mein haan ya nahi sawaalon ki ek series poochh kar predict karta hai."],
      ["Each split picks the question that best separates the outcomes, like 'income above ₹50k?'. Trees are easy to explain but a single deep tree overfits. Random forests and gradient boosting combine many trees and are among the strongest models for tabular data.", "Har split woh sawaal chunta hai jo results ko sabse acche se alag kare, jaise 'income ₹50k se zyaada?'. Trees samjhaane mein aasaan hain par ek gehra tree overfit karta hai. Random forests aur gradient boosting kai trees jodte hain aur tabular data ke liye sabse mazboot models mein hain."],
      ["Has the customer missed a payment? If yes, high risk; if no, check income next.", "Kya customer ne payment miss kiya? Haan to high risk; nahi to agla income check."],
      ["ml-trees"], ["Random forest", "Gradient boosting"]),
    t("Deep learning", "dl", "",
      ["Machine learning with neural networks of many layers, great for images, speech and text.", "Kai layers wale neural networks ke saath machine learning, images, awaaz aur text ke liye badhiya."],
      ["Deep networks learn features directly from raw data: early layers detect simple patterns, later layers combine them into concepts. They need lots of data and compute (GPUs) and power modern vision, speech recognition and LLMs. For most work you start from pretrained models instead of training from scratch.", "Deep networks raw data se seedhe features seekhte hain: shuru ki layers simple patterns pakadti hain, baad ki unhe concepts mein jodti hain. Inhe bahut data aur compute (GPUs) chahiye aur yeh aaj ke vision, speech recognition aur LLMs chalaate hain. Zyaadatar kaam mein shuru se train karne ke bajaye pretrained models se shuru karte ho."],
      ["Speech to text on your phone uses deep learning.", "Phone pe speech to text deep learning use karta hai."],
      ["dl-neural-networks", "what-is-ai"], ["Neural network", "Transformer", "GPU"]),
    t("Deployment", "mlops", "Serving, productionising",
      ["Making a model available for real use, usually as an API or a scheduled job.", "Model ko asli use ke liye available karna, aam taur pe API ya scheduled job ke roop mein."],
      ["Deployment packages the model with its preprocessing (often in Docker), serves it behind an API or runs it in batches, and adds monitoring, scaling and rollback. Safe rollouts use shadow mode or canaries. Most of the real effort in AI projects happens here, after the notebook.", "Deployment model ko uske preprocessing ke saath pack karta hai (aksar Docker mein), API ke peeche serve karta ya batches mein chalata hai, aur monitoring, scaling aur rollback jodta hai. Safe rollouts shadow mode ya canaries use karte hain. AI projects ki zyaadatar asli mehnat notebook ke baad yahin hoti hai."],
      ["Wrapping a fraud model in FastAPI, packaging it with Docker and running it on Kubernetes.", "Fraud model ko FastAPI mein wrap karna, Docker se pack karna aur Kubernetes pe chalana."],
      ["api-serving", "docker", "ml-training-vs-inference"], ["Inference", "Docker", "MLOps"]),
    t("Diffusion model", "dl", "Image generation",
      ["A generative model that creates images by starting from noise and removing it step by step.", "Generative model jo noise se shuru karke step by step use hata kar images banata hai."],
      ["During training the model learns to remove noise from images. To generate, it starts from random noise and repeatedly denoises, guided by a text prompt, until an image appears. Diffusion models power most AI image and some video generators.", "Training mein model images se noise hataana seekhta hai. Banane ke liye random noise se shuru karke, text prompt ke guidance mein, baar baar noise hataata hai jab tak image na ban jaaye. Zyaadatar AI image aur kuch video generators diffusion models se chalte hain."],
      ["Typing 'a tiger in a Mumbai local train, watercolour' and getting a painting.", "'a tiger in a Mumbai local train, watercolour' likh kar painting paana."],
      ["what-is-ai"], ["Generative AI", "Multimodal"]),
    t("Docker", "mlops", "Container",
      ["A tool that packages an app with everything it needs so it runs the same everywhere.", "Tool jo app ko uski har zaroori cheez ke saath pack karta hai taaki har jagah ek jaisa chale."],
      ["A Dockerfile lists the base image, dependencies, code and start command; building it creates an image, and running it creates a container. This removes 'works on my machine' problems and is the standard way to ship ML services to servers and Kubernetes.", "Dockerfile mein base image, dependencies, code aur start command likhe hote hain; build karne se image banti hai, aur chalaane se container. Isse 'mere machine pe chalta hai' wali problems khatam hoti hain, aur ML services ko servers aur Kubernetes tak bhejne ka yahi standard tarika hai."],
      ["Shipping your FastAPI model service as a Docker image to the cloud.", "Apni FastAPI model service ko Docker image ke roop mein cloud pe bhejna."],
      ["docker"], ["Kubernetes", "Deployment"]),
    t("DPO", "llm", "Direct preference optimisation",
      ["A way to fine tune LLMs on pairs of preferred and rejected answers, simpler than RLHF.", "LLMs ko pasand aur na pasand jawaabon ke jodon pe fine tune karne ka tarika, RLHF se simple."],
      ["Given a prompt with a better and a worse response, DPO adjusts the model to make the preferred response more likely, without training a separate reward model. It's widely used to align open models with human preferences after instruction tuning.", "Ek prompt ke behtar aur badtar response diye hon to DPO model ko adjust karta hai taaki pasand wala response zyaada likely ho, bina alag reward model train kiye. Instruction tuning ke baad open models ko insaani pasand se align karne mein kaafi use hota hai."],
      ["Training a support model to prefer short, polite, cited answers over long vague ones.", "Support model ko lambe vague jawaabon ke bajaye chhote, vinamra, cited jawaab pasand karna sikhaana."],
      ["dl-fine-tuning"], ["RLHF", "Fine tuning", "Alignment"]),
    t("Dropout", "dl", "",
      ["Randomly switching off some neurons during training so the network doesn't rely on any single one.", "Training mein kuch neurons randomly band karna taaki network kisi ek pe nirbhar na rahe."],
      ["Dropout is a regularisation method: with, say, 10% probability each neuron's output is set to zero in each training step. This forces redundant, robust patterns and reduces overfitting. It's turned off when the model is used for predictions.", "Dropout regularisation ka tarika hai: maan lo 10% probability se har training step mein har neuron ka output zero kar diya jaata hai. Isse network mazboot, dohraaye patterns seekhta hai aur overfitting kam hoti hai. Predictions ke time ise band kar dete hain."],
      ["Like a team practising with random players sitting out, so everyone learns every role.", "Jaise team random khiladiyon ko bitha kar practice kare, taaki sab har role seekhein."],
      ["dl-neural-networks", "ml-train-test"], ["Regularisation", "Overfitting"]),
    t("Early stopping", "ml", "",
      ["Stopping training when the validation score stops improving, to avoid overfitting.", "Validation score sudharna band ho to training rok dena, overfitting se bachne ke liye."],
      ["As training continues, training loss keeps falling but validation loss eventually rises as the model starts memorising. Early stopping watches validation performance and keeps the best checkpoint. It's standard for gradient boosting and neural networks.", "Training chalti rahe to training loss girta rehta hai par aakhir mein validation loss badhne lagta hai kyunki model ratne lagta hai. Early stopping validation performance dekhta hai aur best checkpoint rakhta hai. Gradient boosting aur neural networks mein standard hai."],
      ["Validation loss is lowest at round 240, so training stops at 260 and keeps round 240.", "Validation loss round 240 pe sabse kam hai, to training 260 pe rukti hai aur round 240 rakhti hai."],
      ["ml-train-test", "ml-trees"], ["Overfitting", "Validation set", "Epoch"]),
    t("Embedding", "llm", "Vector embedding",
      ["A list of numbers that captures the meaning of text, images or items, so similar meanings are close together.", "Numbers ki list jo text, images ya items ka matlab pakadti hai, taaki milte julte matlab paas paas hon."],
      ["An embedding model turns a sentence into a vector of hundreds of numbers. Texts with similar meaning get nearby vectors even with different words. Embeddings power semantic search, RAG, recommendations, clustering and duplicate detection. Always use the same embedding model for documents and queries.", "Embedding model ek sentence ko sainkdon numbers ke vector mein badalta hai. Milte julte matlab wale texts ke vectors paas aate hain, shabd alag hon tab bhi. Embeddings semantic search, RAG, recommendations, clustering aur duplicates dhoondhna chalaati hain. Documents aur queries ke liye hamesha same embedding model use karo."],
      ["'Cheap flights to Goa' and 'low cost tickets Goa' get very close embeddings.", "'Cheap flights to Goa' aur 'low cost tickets Goa' ki embeddings bahut paas hoti hain."],
      ["embeddings", "rag", "math-vectors"], ["Vector database", "Cosine similarity", "Semantic search"]),
    t("Epoch", "dl", "",
      ["One full pass of the training algorithm over the entire training dataset.", "Training algorithm ka poore training dataset pe ek poora chakkar."],
      ["Training usually runs for several epochs, each made of many mini batches. Too few epochs underfit; too many overfit. Watch validation metrics per epoch and use early stopping. Large LLMs often train for about one epoch over enormous data.", "Training aam taur pe kai epochs chalti hai, har ek kai mini batches se bana. Bahut kam epochs underfit; bahut zyaada overfit. Har epoch pe validation metrics dekho aur early stopping use karo. Bade LLMs aksar bahut bade data pe lagbhag ek epoch train hote hain."],
      ["With 10,000 images and batch size 100, one epoch is 100 steps.", "10,000 images aur batch size 100 ke saath ek epoch 100 steps ka hai."],
      ["math-gradients"], ["Batch size", "Early stopping"]),
    t("ETL and ELT", "data", "",
      ["Ways to move data: transform before loading (ETL) or load raw data then transform inside the warehouse (ELT).", "Data le jaane ke tarike: load se pehle transform (ETL) ya raw data load karke warehouse ke andar transform (ELT)."],
      ["ETL cleans data before it lands, useful when data must be masked first. ELT loads raw data into a cloud warehouse and transforms it with SQL (often dbt), which is the common modern approach because raw data can be reprocessed when logic changes.", "ETL data aane se pehle saaf karta hai, jab data pehle mask karna zaroori ho tab kaam ka. ELT raw data cloud warehouse mein load karke SQL (aksar dbt) se transform karta hai, jo aaj ka common tarika hai kyunki logic badalne pe raw data dobara process ho sakta hai."],
      ["Loading raw app events into BigQuery, then building clean tables with dbt.", "Raw app events BigQuery mein load karna, phir dbt se saaf tables banana."],
      ["data-pipelines"], ["Data pipeline", "Data warehouse"]),
    t("Evals (evaluation)", "eval", "Eval set, eval suite",
      ["A repeatable set of test cases and scoring rules that measures whether an AI system works well.", "Test cases aur scoring rules ka dohraaya ja sakne wala set jo naapta hai AI system acche se kaam karta hai ya nahi."],
      ["For LLM apps, define what good means, collect real examples (common, edge cases, past failures), and score them with code checks where possible and rubrics (human or LLM judge) where needed. Run evals on every prompt or model change, like unit tests, and add each new production failure. Evals are what separate demos from reliable products.", "LLM apps ke liye accha ka matlab tay karo, asli examples ikattha karo (common, edge cases, purane failures), aur jahan ho sake code checks se, jahan zaroori rubrics (insaan ya LLM judge) se score karo. Har prompt ya model change pe unit tests ki tarah evals chalao, aur har naya production failure jodo. Evals hi demos ko reliable products se alag karte hain."],
      ["100 real customer questions with expected answers, rerun after every prompt change.", "Expected jawaabon ke saath 100 asli customer sawaal, har prompt change ke baad dobara chalaaye."],
      ["llm-evals", "ai-prd"], ["LLM as judge", "Benchmark", "Hallucination"]),
    t("Explainability", "eval", "Interpretability, XAI",
      ["Understanding and showing why a model made a particular prediction.", "Samajhna aur dikhana ki model ne koi prediction kyun kiya."],
      ["In lending, healthcare and hiring, people and regulators need reasons. Tools like SHAP show which features pushed a prediction up or down; simpler models are easier to explain. For LLMs, showing sources (citations) is a practical form of explainability.", "Lending, healthcare aur hiring mein logon aur regulators ko wajah chahiye. SHAP jaise tools dikhate hain kaunse features ne prediction upar ya neeche kiya; simple models samjhaane mein aasaan hain. LLMs ke liye sources (citations) dikhana explainability ka practical roop hai."],
      ["'Loan declined mainly because of 3 missed payments and high EMI to income ratio.'", "'Loan mainly 3 miss hue payments aur zyaada EMI to income ratio ki wajah se reject hua.'"],
      ["ml-features", "security-compliance"], ["Bias (in data and models)", "Feature"])
  ];
})());

if (typeof module !== "undefined" && module.exports) module.exports = { GLOSSARY_TERMS };
